        en: 'On the lower River Homem, between the Cavadouro bridge and the Cávado confluence, the Recreational Fishing Zone lets you keep up to 6 trout a day (20 cm minimum), using a single-hook lure or worm. Further up, towards Gerês, there is a catch-and-release-only stretch and closed zones, so check the map for the sector you are in.',
