        en: 'A 2.5 km stretch at the head of the Torrão reservoir, between the A4 bridge at Formão and the Báia bridge, classified by ICNF as a reserved fishing zone and open every day of the year. The special permit is free, but everything caught goes back, except species whose release is prohibited.',
