      tecnica: { pt: 'Surfcasting com cana longa; lançar perto da preia-mar com mar calmo e procurar os canais entre bancos de areia quando há ondulação. Iscos: minhoca, casulo, lula; caranguejo para o sargo.', en: 'Surfcasting with a long rod; cast around high tide in calm seas and work the channels between sandbars when there is swell. Baits: worms, lugworm, squid; crab for seabream.' },
      desc: {
        pt: 'Areal aberto e pouco urbanizado entre a Praia de Mira e a Tocha, com bancos de areia e canais que mudam a cada temporal. À noite é terreno clássico para linguado e robalo; de dia o sargo entra junto às manchas de rocha com mexilhão.',
        en: 'A wide, lightly built-up beach between Praia de Mira and Tocha, with sandbars and gullies that shift after every storm. At night it is classic ground for sole and bass; by day seabream move in around the mussel-covered rock patches.',
      },
      aviso: { pt: 'Na época balnear a pesca lúdica não é permitida nas zonas de banhos entre o nascer e o pôr do sol (edital de praia). Licença de pesca lúdica obrigatória.', en: 'During bathing season recreational fishing is not allowed in bathing areas between sunrise and sunset (beach notice). A recreational fishing licence is required.' },
