      tecnica: { pt: 'Bóia ou fundo ligeiro (chumbos até ~100 g) com isco natural: camarão, peixe miúdo ou bivalves. Uma cana bem montada chega; o sargo morde mais no outono.', en: 'Float or light bottom rigs (sinkers up to ~100 g) with natural bait: shrimp, small fish or shellfish. One well-rigged rod is enough; seabream bite best in autumn.' },
      desc: {
        pt: 'A península de Peniche é o pesqueiro de rocha mais procurado do Oeste: um estudo da DGRM aponta a faixa do Cabo Carvoeiro ao farol e o Forte da Luz como os pontos mais concorridos. Na Papoa, as lajes viradas a norte rendem sargos de bom porte com mar picado.',
        en: 'The Peniche peninsula is the busiest rock-fishing ground on the Oeste coast: a DGRM study names the Cabo Carvoeiro–lighthouse stretch and Forte da Luz as the main hotspots. At Papoa, the north-facing ledges produce good-sized seabream when the sea is choppy.',
      },
      aviso: { pt: 'Só para pescadores experientes: houve resgates por pescadores isolados pela maré no ilhéu da Papoa (2022) e uma queda de 10 m da arriba junto ao Forte da Luz (2024).', en: 'Experienced anglers only: there have been rescues of anglers cut off by the tide on the Papoa islet (2022) and a 10 m cliff fall near Forte da Luz (2024).' },
