      aviso: { pt: 'Concessão de pesca: licença especial diária na CM Pampilhosa da Serra (máx. 3 por lote). Truta 1 mar–31 jul, mínimo 20 cm, máx. 6/dia; lotes 1 e 3 só pesca sem morte.', en: 'Fishing concession: daily special permit from Pampilhosa da Serra council (max 3 per beat). Trout 1 Mar–31 Jul, min 20 cm, max 6/day; beats 1 and 3 are catch-and-release only.' },
