      especies: { pt: 'Corvina', en: 'Meagre (corvina)' },
      tecnica: { pt: 'Fundo com iscos grandes (caranguejo, choco, lula, camarão vivo); anzol 3/0 ou maior', en: 'Bottom fishing with big baits (crab, cuttlefish, squid, live shrimp); 3/0 hooks or larger' },
      desc: {
        pt: 'No troço alto do estuário, entre Alverca e Alhandra, a margem é conhecida pelas corvinas que sobem o Tejo para desovar e que podem passar dos 15 kg. Iscos grandes e uma estralha curta junto à chumbada ajudam, porque a corvina come rente ao fundo.',
        en: 'In the upper estuary between Alverca and Alhandra, the bank is known for meagre that run up the Tagus to spawn and can top 15 kg. Big baits and a short snood close to the sinker help, as meagre feed hard on the bottom.',
      },
      aviso: { pt: 'Estuário do Tejo (Portaria n.º 330/2026/1): no máximo 2 canas e 3 anzóis por pescador; proibido pescar a menos de 100 m de pontões de desembarque, fortes, faróis e rampas de nadadores-salvadores, a menos de 300 m de cais de acostagem e em zonas balneares (200 m da margem) durante a época balnear. Tamanho mínimo da corvina: 42 cm; devolva os exemplares pequenos.', en: 'Tagus estuary (Portaria 330/2026/1): no more than 2 rods per angler; no fishing within 100 m of landing pontoons, forts, lighthouses and lifeguard ramps, within 300 m of berths, or in bathing areas (200 m from the shore) during the bathing season. Meagre minimum size: 42 cm; release small fish.' },
      tags: { pt: ['Corvina', 'Peixe grande', 'Estuário', 'Primavera-verão'], en: ['Meagre', 'Big fish', 'Estuary', 'Spring-summer'] },
