      desc: {
        pt: 'Areal contínuo e pouco urbanizado entre a Comporta e o Pêgo, com fundo de areia cortado por valas onde robalos e douradas entram para comer. As sessões ao fim da tarde e à noite são as mais faladas pelos pescadores que vêm de Setúbal pelo ferry de Tróia.',
        en: 'A long, barely developed stretch of sand between Comporta and Pêgo, with a sandy bottom cut by gutters where bass and bream move in to feed. Evening and night sessions are what anglers coming over from Setúbal on the Tróia ferry talk about most.',
      },
