      season: { pt: 'Outono e primavera; o sargo junta-se nas rochas no inverno (atenção ao defeso)', en: 'Autumn and spring; seabream gather on the rocks in winter (mind the closed season)' },
      especies: { pt: 'Sargo, robalo, dourada', en: 'White seabream, sea bass, gilthead bream' },
      tecnica: { pt: 'Bóia e fundo a partir das lajes, com iscos de marisco e engodo', en: 'Float and bottom fishing from the rock shelves, with shellfish baits and groundbait' },
      desc: {
        pt: 'Os cerca de 3,5 km de costa rochosa a sul da praia do Almograve, até ao porto de pesca da Lapa de Pombas, são uma das zonas acompanhadas pelos estudos de pesca lúdica do Parque Natural. O sargo é o peixe-alvo, sobretudo nas concentrações de inverno junto às pedras.',
        en: 'The roughly 3.5 km of rocky shore south of Almograve beach, down to the Lapa de Pombas fishing harbour, is one of the areas monitored by the natural park\'s recreational-fishing studies. Seabream is the main target, especially when they bunch up along the rocks in winter.',
      },
      aviso: { pt: 'Parque Natural do Sudoeste Alentejano: defeso do sargo para pesca apeada de 1 a 28 de fevereiro e do bodião de 1 de março a 31 de maio. Fique a mais de 100 m do porto da Lapa de Pombas. Mais a sul, a partir do barranco do Cavaleiro (Cabo Sardão), a pesca lúdica é interdita.', en: 'Southwest Alentejo Natural Park: seabream closed season for shore anglers in February (sources say until 15 March, so check) and ballan wrasse closed from 1 March to 31 May. Stay more than 100 m from Lapa de Pombas harbour. Further south, from the Cavaleiro ravine (Cabo Sardão), recreational fishing is banned.' },
      tags: { pt: ['Sargo', 'Pesca à rocha', 'Costa Vicentina', 'Inverno'], en: ['Seabream', 'Rock fishing', 'Vicentine Coast', 'Winter'] },
      quality: 3,
