      season: { pt: 'Outono apontado como boa época para achigãs grandes; o início do verão tende a ser mais lento', en: 'Autumn is singled out as good for big bass; early summer tends to be slower' },
      especies: { pt: 'Achigã, carpa (exemplares acima de 10 kg), pimpão', en: 'Largemouth bass, carp (fish over 10 kg), Prussian carp (pimpão)' },
      tecnica: { pt: 'Spinning e popper para achigã; pesca à carpa ao fundo; barco ou caiaque para chegar às enseadas', en: 'Spinning and poppers for bass; bottom fishing for carp; a boat or kayak to reach the coves' },
      desc: {
        pt: 'Com quase 2000 hectares, cheia de braços, enseadas e ilhotas, é uma das maiores albufeiras do país e um destino conhecido para o achigã. Há guias locais com barco, e as carpas grandes são a alternativa para quem prefere esperar ao fundo.',
        en: 'At almost 2,000 hectares and full of arms, coves and islets, it is one of the largest reservoirs in the country and a known destination for largemouth bass. Local guides run boat trips, and the big carp are the alternative for anglers who\'d rather wait on the bottom.',
      },
      aviso: { pt: 'Licença de pesca em águas interiores (ICNF). O lagostim-vermelho e a perca-sol não podem ser devolvidos à água. Recomenda-se devolver os achigãs grandes.', en: 'Inland-waters fishing licence (ICNF) required. Red swamp crayfish and pumpkinseed may not be returned to the water. Releasing big bass is encouraged.' },
