      desc: {
        pt: 'Albufeira antiga, construída no século XIX para servir a mina, hoje rodeada de sombra e com praia fluvial. O achigã é o peixe da casa e responde melhor a vinis trabalhados devagar do que a amostras de superfície.',
        en: 'An old reservoir built in the 19th century to serve the mine, now shaded by trees and with a river beach. Largemouth bass is the resident fish and responds better to slowly worked soft plastics than to surface lures.',
      },
      aviso: { pt: 'Licença de pesca em águas interiores (ICNF). Praia fluvial vigiada de 1 de junho a 15 de setembro: não pesque na zona balnear nessa altura. Devolva os achigãs pequenos.', en: 'Inland-waters fishing licence (ICNF) required. The river beach is lifeguarded from 1 June to 15 September, so don\'t fish in the swimming area during that period. Release small bass.' },
