      especies: { pt: 'Cavala, carapau, sargo, dourada, choupa e pargo-legítimo; ao largo, tintureira e anequim (captura e solta), atuns e dourado-do-mar', en: 'Mackerel, horse mackerel, white and gilthead seabream, black seabream and dentex; offshore, blue and mako shark (catch and release), tuna and mahi-mahi' },
      tecnica: { pt: 'Pesca de fundo com camarão e berbigão sobre o recife (20–30 m); sardinha como engodo nas saídas ao tubarão', en: 'Bottom fishing with shrimp and cockle over 20–30 m reefs; sardine chum on shark trips' },
      desc: {
        pt: 'Da marina saem passeios de três horas ao recife, a menos de uma milha da costa, e saídas mais longas ao tubarão e ao peixe de alto mar. É uma opção prática para quem está alojado em Albufeira e quer pescar sem levar material.',
        en: 'Three-hour reef trips leave the marina for grounds less than a mile offshore, alongside longer shark and offshore outings. It is a convenient option for anyone staying in Albufeira who wants to fish without bringing gear.',
      },
