      desc: {
        pt: 'O molhe da Ponta da Areia marca a entrada do Guadiana e é dos pesqueiros mais concorridos do sotavento, porque a corrente da maré traz robalos e, com sorte, corvinas. Mais acima, a margem junto à cidade dá fundo tranquilo para douradas e sargos.',
        en: 'The Ponta da Areia breakwater marks the mouth of the Guadiana and is one of the busiest marks in the eastern Algarve, as tidal flow brings in sea bass and, with luck, meagre. Upriver, the town bank offers quieter bottom fishing for bream.',
      },
      aviso: { pt: 'Pesca embarcada proibida na barra e no canal de navegação. O Guadiana é rio de fronteira: rio acima podem aplicar-se regras próprias — confirme antes de pescar. Ponta do molhe escorregadia e exposta à ondulação.', en: 'Boat fishing is banned in the bar and navigation channel. The Guadiana is a border river and specific rules may apply upstream — check before fishing. The breakwater tip is slippery and exposed to swell.' },
