      especies: { pt: 'Sargo, dourada, robalo, choupa, pargo e, à bóia, carapau e cavala', en: 'White and gilthead seabream, sea bass, black seabream, red porgy and, on the float, horse mackerel and chub mackerel' },
      tecnica: { pt: 'Bóia com sardinha, gamba ou camarão vivo; fundo também é possível', en: 'Float fishing with sardine, prawn or live shrimp; bottom fishing also works' },
      desc: {
        pt: 'Os rochedos a norte da Praia do Amado, até à Pedra do Lago e ao Pontal, são terreno clássico de pesca à bóia em plena Costa Vicentina, com água funda e mar aberto. Há guias locais que levam pescadores a pé pelos trilhos de pescador desta costa, com licença e material incluídos.',
        en: 'The rocks north of Praia do Amado, up to Pedra do Lago and the Pontal headland, are classic Costa Vicentina float-fishing ground, with deep water and open sea. Local guides take anglers on foot along the fishermen\'s paths of this coast, licence and gear included.',
      },
      aviso: { pt: 'Parque Natural do Sudoeste Alentejano e Costa Vicentina: defeso do sargo na pesca apeada de 1 a 28 de fevereiro e do bodião de 1 de março a 31 de maio. A Arrifana e a Pedra da Agulha (mais a norte) estão interditas. Arribas altas e ondulação forte: não pesque sozinho nem com mar grosso.', en: 'Southwest Alentejo and Vicentine Coast Natural Park: shore closed season for white seabream 1–28 February and for wrasse 1 March–31 May. Arrifana and Pedra da Agulha (further north) are off-limits. High cliffs and heavy swell: never fish alone or in big seas.' },
      tags: { pt: ['Costa Vicentina', 'Pesca à bóia', 'Natureza', 'Guias locais'], en: ['Vicentine Coast', 'Float fishing', 'Wild coast', 'Local guides'] },
      quality: 4,
