      especies: { pt: 'Achigã e carpa', en: 'Largemouth bass and carp' },
      tecnica: { pt: 'Amostras para o achigã a partir da margem; fundo com isco para a carpa', en: 'Lure fishing for bass from the bank; bait bottom fishing for carp' },
      desc: {
        pt: 'A maior albufeira do sotavento algarvio estende-se por vales de xisto e oferece muitos quilómetros de margem para procurar o achigã com amostra. Tem também uma zona balnear vigiada no verão, o que a torna uma escapada fácil para famílias.',
        en: 'The largest reservoir in the eastern Algarve winds through schist valleys, with miles of bank to search for largemouth bass on lures. It also has a lifeguarded bathing area in summer, making it an easy family day out.',
      },
      aviso: { pt: 'Exige licença de pesca em águas interiores (ICNF), não a licença de mar. Albufeira de abastecimento público: sem motores e fora da zona balnear. Confirme defesos e regras locais no edital anual do ICNF.', en: 'Requires an inland-waters fishing licence (ICNF), not the sea licence. It supplies drinking water: no motorboats and keep away from the bathing area. Check closed seasons and local rules in ICNF\'s annual notice.' },
