      especies: { pt: 'Espadim-azul e branco, dourada-do-mar, serra (wahoo), atuns (patudo, albacora), agulhão; no fundo, charuteiro e pargo', en: 'Blue and white marlin, mahi-mahi, wahoo, tunas (bigeye, yellowfin), spearfish; amberjack and snapper on the bottom' },
      tecnica: { pt: 'Corrico de alto mar e pesca de fundo; saídas combinadas de meio dia ou dia inteiro', en: 'Offshore trolling and bottom fishing; combined half-day or full-day trips' },
      desc: {
        pt: 'A marina no centro do Funchal é o ponto de partida mais prático para quem fica na capital: há charters para corrico ao espadim e saídas de fundo, com águas profundas a poucos minutos da baía. Boa opção para uma primeira experiência de pesca no mar, sem ter de atravessar a ilha.',
        en: 'The marina in central Funchal is the handiest departure point if you are staying in the capital, with charters for marlin trolling and bottom fishing and deep water a few minutes outside the bay. A good option for a first sea-fishing trip without crossing the island.',
      },
      aviso: { pt: 'A Reserva Natural Parcial do Garajau, a leste do Funchal, é zona interdita à pesca. A licença costuma estar incluída nos charters; os espadins são normalmente devolvidos ao mar.', en: 'The Garajau Partial Nature Reserve, east of Funchal, is closed to fishing. Charters usually include the licence; billfish are normally released.' },
