      name: 'Porto Moniz e Seixal — pesca à pedra',
      region: 'Madeira',
      location: { pt: 'Porto Moniz e Seixal, costa norte da Madeira', en: 'Porto Moniz and Seixal, Madeira north coast' },
      bgClass: 'spot-bg--acores',
