      desc: {
        pt: 'É a única lagoa de São Miguel com lúcio-perca, o que a torna o destino certo para quem pesca predadores em água doce; a carpa é tão abundante que chega a ser incómoda. Dá para contornar a lagoa a pé e combinar a pescaria com as termas e o cozido das Furnas.',
        en: 'It is the only lake on São Miguel with zander, making it the pick for freshwater predator anglers; carp are so plentiful they can be a nuisance. You can walk right round the lake and pair the session with the Furnas hot springs and the famous volcanic stew.',
      },
      aviso: { pt: 'Exige licença de pesca em águas interiores do Serviço Florestal de Ponta Delgada. Na margem norte há fumarolas e zonas vedadas: não as atravesse. Respeite tamanhos mínimos.', en: 'Requires an inland-water fishing licence from the Ponta Delgada Forestry Service. There are fumaroles and fenced-off areas on the north shore: keep out of them. Respect minimum sizes.' },
