      especies: { pt: 'Dourada, pargo, dentão, besugo, choupa, cavala, peixe-porco; no verão, dourado e marlim-branco', en: 'Gilthead bream, red porgy, dentex, axillary bream, black bream, chub mackerel, grey triggerfish; mahi-mahi and white marlin in summer' },
