      desc: {
        pt: 'Os barcos de pesca de Tavira saem da doca das Quatro Águas e de Cabanas, cruzam a barra da Ria Formosa e fundeiam sobre recifes a poucas milhas da costa. As saídas de fundo de 2,5 a 5 horas são uma boa estreia para famílias; de agosto a outubro também há saídas de alto mar ao dourado e aos marlins.',
        en: 'Tavira\'s fishing boats leave from the Quatro Águas dock and from Cabanas, cross the Ria Formosa inlet and anchor over reefs a few miles out. The 2.5–5 hour bottom-fishing trips are an easy first outing for families, and from August to October there are also offshore trips for mahi-mahi and marlin.',
      },
      aviso: { pt: 'Nem todos os operadores incluem a licença de pesca embarcada: confirme antes de reservar. Não se pesca na barra nem nos canais; o atum-rabilho só pode ser retido em pesca-turística autorizada.', en: 'Not every operator includes the boat fishing licence, so check before booking. No fishing in the inlet or channels; bluefin tuna may only be kept on licensed fishing-tourism trips.' },
