      especies: { pt: 'Marlim-branco, marlim-azul, dourado, bonito, atum-voador, dentão; no fundo, dourada e robalo', en: 'White marlin, blue marlin, mahi-mahi, skipjack, albacore, dentex; on the bottom, gilthead bream and sea bass' },
