        en: 'Some of the Algarve\'s best-known big-game boats sail from Olhão Marina, heading offshore where marlin and mahi-mahi pass from early summer to October. Half-day bottom-fishing trips run too, but prices are per boat (up to 6 people), so it pays to fill it.',
