      aviso: { pt: 'Praia concessionada: sem pesca na zona de banhos na época balnear. Use só os acessos sinalizados: as dunas são frágeis.', en: 'Supervised beach: no fishing in the bathing area in season. Use only the marked paths — the dunes are fragile.' },
