      aviso: { pt: 'A Polícia Marítima fiscaliza a licença de pesca nesta praia. Praia concessionada: sem pesca na zona de banhos na época balnear. Do lado da ria aplicam-se as regras da Ria Formosa (2 canas, 3 anzóis).', en: 'The Maritime Police check fishing licences on this beach. Supervised beach: no fishing in the bathing area in season. On the lagoon side Ria Formosa rules apply (2 rods, 3 hooks).' },
