      desc: {
        pt: 'A baía abrigada de Machico, a 10 minutos do aeroporto, é ponto de partida de saídas de pesca de fundo em barcos pequenos, à procura de pargo, bica e peixe-porco sobre fundos rochosos perto da costa. Em terra é um sítio calmo para principiantes apanharem sargo e bodião, mas as duas praias da baía obrigam a pescar longe das zonas de banho.',
        en: 'Machico\'s sheltered bay, ten minutes from the airport, is a starting point for small-boat bottom-fishing trips targeting red porgy, pandora and triggerfish over rocky ground close to shore. From land it is a calm spot for beginners after seabream and wrasse, but the bay\'s two beaches mean you must keep well away from bathing areas.',
      },
      aviso: { pt: 'Na Madeira é proibido pescar nas concessões balneares e a menos de 300 m de locais habituais de banho (Portaria 484/2016, JORAM). Licença lúdica no portal Simplifica. Charuteiro/írio acima de 10 kg e badejo abaixo de 2 kg não podem ser retidos.', en: 'In Madeira, fishing is banned in beach concession waters and within 300 m of places normally used for bathing (Portaria 484/2016, JORAM). Recreational licence via the Simplifica portal. Amberjack over 10 kg and island grouper (badejo) under 2 kg may not be kept.' },
