        en: 'Rabo de Peixe\'s fishing harbour on São Miguel\'s north coast is the base for traditional trips on local fishermen\'s boats, bottom fishing for pandora and triggerfish and squid towards evening. It is a cheaper, more hands-on alternative to big game out of Ponta Delgada, but the north coast is more exposed and trips depend heavily on the wind.',
