        en: 'On Flores deep water comes right up to the shore, and at dusk the coves of Santa Cruz and Lajes harbour produce bluefish and barracuda on spinning gear, with a chance of red porgy or amberjack. It suits anglers with strong tackle and some experience: the island is remote, the sea changes fast and there are almost no operators bookable online.',
